package com.bank.auditfmt;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AuditFormatDemo {
    private static final Logger log = Logger.getLogger("AuditFormat");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> approvers = List.of(
            new Employee(1L, "Rajesh"),
            new Employee(2L, "Priya"),
            new Employee(3L, "Amit")
        );
        List<Employee> none = List.of();

        AuditFormatService service = new AuditFormatService();
        log.info(() -> "Approvers: " + service.formatNames(approvers));
        log.info(() -> "Approvers (empty): " + service.formatNames(none));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    Employee(Long id, String name) { this.id = id; this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/AuditFormatService.java ───
class AuditFormatService {
    // joining(delimiter, prefix, suffix): commas between names, brackets around the whole.
    String formatNames(List<Employee> employees) {
        return employees.stream()
            .map(Employee::getName)
            .collect(joining(", ", "[", "]"));
    }
}
